package app.tsuyu.mobile;

import android.Manifest;
import android.app.*;
import android.content.*;
import android.content.pm.PackageManager;
import android.graphics.*;
import android.media.MediaRecorder;
import android.net.Uri;
import android.os.*;
import android.text.*;
import android.util.Base64;
import android.view.*;
import android.view.inputmethod.InputMethodManager;
import android.widget.*;
import androidx.recyclerview.widget.*;
import androidx.core.content.FileProvider;
import com.google.firebase.database.*;
import org.json.*;
import java.io.*;
import java.util.*;

public class ChatActivity extends Activity {
    public static String activePeer=""; String peer,chat,peerName="Tsuyu",peerAvatar=""; LinearLayout root,replyBar; TextView title,sub,replyText; EditText input; RecyclerView list; MsgAdapter adapter; final ArrayList<Msg> msgs=new ArrayList<>(); ValueEventListener msgListener,presListener,typingListener; String replyTo=""; MediaRecorder recorder; File recFile; long recStart; Button recBtn; int textSize=15;
    public static boolean isActive(String p){return p!=null&&p.equals(activePeer);} 
    @Override protected void onCreate(Bundle b){super.onCreate(b);peer=getIntent().getStringExtra("peerUid");if(peer==null||peer.isEmpty()){finish();return;}chat=Rt.chatId(Rt.uid(),peer);textSize=getSharedPreferences("ui",0).getInt("textSize",15);build();loadPeer();listen();}
    @Override protected void onResume(){super.onResume();activePeer=peer;Rt.online();}
    @Override protected void onPause(){super.onPause();if(peer.equals(activePeer))activePeer="";Rt.stopTyping(chat);}
    @Override protected void onDestroy(){super.onDestroy();detach();}

    private void build(){root=Tui.root(this);LinearLayout top=Tui.row(this);Button back=Tui.iconButton(this,R.drawable.ic_back);LinearLayout names=new LinearLayout(this);names.setOrientation(LinearLayout.VERTICAL);title=Tui.text(this,"Tsuyu",18,true);sub=Tui.text(this,"подключение...",12,false);names.addView(title);names.addView(sub);Button more=Tui.iconButton(this,R.drawable.ic_more);top.addView(back,new LinearLayout.LayoutParams(dp(46),dp(52)));top.addView(names,new LinearLayout.LayoutParams(0,dp(52),1));top.addView(more,new LinearLayout.LayoutParams(dp(46),dp(52)));root.addView(top);list=new RecyclerView(this);list.setLayoutManager(new LinearLayoutManager(this));adapter=new MsgAdapter();list.setAdapter(adapter);root.addView(list,new LinearLayout.LayoutParams(-1,0,1));replyBar=Tui.row(this);replyBar.setPadding(dp(12),dp(4),dp(12),dp(4));replyText=Tui.text(this,"",13,false);Button cancel=Tui.iconButton(this,R.drawable.ic_close);replyBar.addView(replyText,new LinearLayout.LayoutParams(0,dp(42),1));replyBar.addView(cancel,new LinearLayout.LayoutParams(dp(40),dp(40)));replyBar.setVisibility(View.GONE);root.addView(replyBar);LinearLayout media=Tui.row(this);Button photo=Tui.iconButton(this,R.drawable.ic_photo);Button video=Tui.iconButton(this,R.drawable.ic_video);Button circle=Tui.iconButton(this,R.drawable.ic_circle);Button audio=Tui.iconButton(this,R.drawable.ic_audio);media.addView(photo,new LinearLayout.LayoutParams(0,dp(44),1));media.addView(video,new LinearLayout.LayoutParams(0,dp(44),1));media.addView(circle,new LinearLayout.LayoutParams(0,dp(44),1));media.addView(audio,new LinearLayout.LayoutParams(0,dp(44),1));root.addView(media);LinearLayout bar=Tui.row(this);input=Tui.input(this,"Сообщение");Button send=Tui.iconButton(this,R.drawable.ic_send);recBtn=Tui.iconButton(this,R.drawable.ic_mic);bar.addView(input,new LinearLayout.LayoutParams(0,dp(58),1));bar.addView(recBtn,new LinearLayout.LayoutParams(dp(52),dp(52)));bar.addView(send,new LinearLayout.LayoutParams(dp(52),dp(52)));root.addView(bar);setContentView(root);back.setOnClickListener(v->finish());cancel.setOnClickListener(v->clearReply());more.setOnClickListener(v->chatMenu());send.setOnClickListener(v->sendText());photo.setOnClickListener(v->pick("image/*",11));video.setOnClickListener(v->pick("video/*",12));circle.setOnClickListener(v->pick("video/*",14));audio.setOnClickListener(v->pick("audio/*",13));recBtn.setOnClickListener(v->toggleRecord());input.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int st,int c,int a){}public void onTextChanged(CharSequence s,int st,int b,int c){Rt.typing(chat,s.length()>0?"typing":"");}public void afterTextChanged(Editable e){}});new ItemTouchHelper(new ItemTouchHelper.SimpleCallback(0,ItemTouchHelper.RIGHT){public boolean onMove(RecyclerView r,RecyclerView.ViewHolder a,RecyclerView.ViewHolder b){return false;}public void onSwiped(RecyclerView.ViewHolder h,int d){int p=h.getBindingAdapterPosition();if(p>=0&&p<msgs.size())setReply(msgs.get(p));adapter.notifyItemChanged(p);}}).attachToRecyclerView(list);} 
    private void loadPeer(){Rt.getProfile(peer,new Rt.Got(){public void ok(JSONObject o){peerName=o.optString("name",o.optString("username","Tsuyu"));peerAvatar=o.optString("avatar","");title.setText(peerName);TsuyuApp.app().index.profile(o);}public void fail(String e){title.setText("Tsuyu");}});} 
    private void listen(){DatabaseReference m=Rt.db().child("chats").child(chat).child("messages");msgListener=new ValueEventListener(){public void onDataChange(DataSnapshot root){msgs.clear();for(DataSnapshot s:root.getChildren())parseMsg(s);Collections.sort(msgs,(a,b)->Long.compare(a.ts,b.ts));adapter.notifyDataSetChanged();if(!msgs.isEmpty())list.scrollToPosition(msgs.size()-1);}public void onCancelled(DatabaseError e){Tui.toast(ChatActivity.this,e.getMessage());}};m.limitToLast(300).addValueEventListener(msgListener);presListener=new ValueEventListener(){public void onDataChange(DataSnapshot s){boolean on=Boolean.TRUE.equals(s.child("online").getValue(Boolean.class));long last=lv(s.child("lastSeen"),0);if(on)sub.setText(status("online","онлайн"));else sub.setText(status("lastSeen","был(а) ")+Tui.time(last));}public void onCancelled(DatabaseError e){}};Rt.db().child("presence").child(peer).addValueEventListener(presListener);typingListener=new ValueEventListener(){public void onDataChange(DataSnapshot s){long at=lv(s.child("at"),0);if(System.currentTimeMillis()-at<3500)sub.setText(status("typing","печатает..."));}public void onCancelled(DatabaseError e){}};Rt.db().child("typing").child(chat).child(peer).addValueEventListener(typingListener);} 
    private void parseMsg(DataSnapshot s){try{JSONObject p=Rt.decrypt(chat,s.getKey(),s);Msg m=new Msg();m.id=s.getKey();m.sender=s.child("sender").getValue(String.class);m.receiver=s.child("receiver").getValue(String.class);m.mine=Rt.uid().equals(m.sender);m.ts=lv(s.child("ts"),lv(s.child("clientAt"),0));m.edited=Boolean.TRUE.equals(s.child("edited").getValue(Boolean.class));m.payload=p;m.type=p.optString("type","text");m.text=p.optString("text","");m.reply=p.optString("replyTo","");m.media=p.optJSONArray("media");m.preview=Rt.preview(p);long rc=0;for(DataSnapshot r:s.child("reactions").getChildren())rc+=r.getChildrenCount();m.reactions=rc;msgs.add(m);JSONObject cached=new JSONObject().put("id",m.id).put("chatId",chat).put("sender",m.sender).put("receiver",m.receiver).put("text",m.text).put("type",m.type).put("decryptedPreview",m.preview).put("ts",m.ts).put("edited",m.edited).put("payload",p.toString());TsuyuApp.app().index.message(cached);}catch(Exception e){Msg m=new Msg();m.id=s.getKey();m.preview="Не удалось расшифровать";m.ts=lv(s.child("ts"),0);msgs.add(m);}}
    private void sendText(){String t=input.getText().toString().trim();if(t.isEmpty())return;String rep=replyTo;input.setText("");clearReply();Rt.sendText(peer,t,rep,new Rt.Done(){public void ok(){}public void fail(String e){Tui.toast(ChatActivity.this,e);}});} 
    private void sendMedia(ArrayList<MediaTools.Pack> packs){String t=input.getText().toString().trim();String rep=replyTo;input.setText("");clearReply();Rt.sendMedia(peer,t,packs,rep,new Rt.Done(){public void ok(){}public void fail(String e){Tui.toast(ChatActivity.this,e);}});} 
    private void pick(String mime,int req){Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.addCategory(Intent.CATEGORY_OPENABLE);i.setType(mime);startActivityForResult(i,req);} 
    @Override protected void onActivityResult(int r,int c,Intent d){super.onActivityResult(r,c,d);if(c!=RESULT_OK||d==null||d.getData()==null)return;Uri u=d.getData();TsuyuApp.bg(()->{try{MediaTools.Pack p;if(r==11)p=MediaTools.image(this,u);else if(r==13)p=MediaTools.binary(this,u,"audio",false);else if(r==14)p=MediaTools.binary(this,u,"circle",true);else p=MediaTools.binary(this,u,"video",false);ArrayList<MediaTools.Pack> a=new ArrayList<>();a.add(p);TsuyuApp.ui(()->sendMedia(a));}catch(Exception e){TsuyuApp.ui(()->Tui.toast(this,e.getMessage()));}});} 
    private void toggleRecord(){if(recorder!=null){stopRecord();return;}if(Build.VERSION.SDK_INT>=23&&checkSelfPermission(Manifest.permission.RECORD_AUDIO)!=PackageManager.PERMISSION_GRANTED){requestPermissions(new String[]{Manifest.permission.RECORD_AUDIO},77);return;}try{File dir=new File(getCacheDir(),"voice");dir.mkdirs();recFile=File.createTempFile("voice_",".m4a",dir);recorder=new MediaRecorder();recorder.setAudioSource(MediaRecorder.AudioSource.MIC);recorder.setOutputFormat(MediaRecorder.OutputFormat.MPEG_4);recorder.setAudioEncoder(MediaRecorder.AudioEncoder.AAC);recorder.setAudioEncodingBitRate(64000);recorder.setAudioSamplingRate(44100);recorder.setOutputFile(recFile.getAbsolutePath());recorder.prepare();recorder.start();recStart=System.currentTimeMillis();recBtn.setText("■");Tui.toast(this,"Запись голоса...");}catch(Exception e){recorder=null;Tui.toast(this,e.getMessage());}}
    private void stopRecord(){try{recorder.stop();}catch(Exception ignored){}try{recorder.release();}catch(Exception ignored){}recorder=null;recBtn.setText("🎙");int dur=(int)Math.max(1,(System.currentTimeMillis()-recStart)/1000);TsuyuApp.bg(()->{try{MediaTools.Pack p=MediaTools.fromFile(recFile,"voice",dur);ArrayList<MediaTools.Pack> a=new ArrayList<>();a.add(p);TsuyuApp.ui(()->sendMedia(a));}catch(Exception e){TsuyuApp.ui(()->Tui.toast(this,e.getMessage()));}});} 
    private void setReply(Msg m){replyTo=m.id;replyText.setText("Ответ на: "+m.preview);replyBar.setVisibility(View.VISIBLE);replyBar.setAlpha(0);replyBar.animate().alpha(1).setDuration(160).start();input.requestFocus();((InputMethodManager)getSystemService(INPUT_METHOD_SERVICE)).showSoftInput(input,0);}private void clearReply(){replyTo="";replyBar.setVisibility(View.GONE);} 
    private void messageMenu(Msg m){String[] items=m.mine?new String[]{"Ответить","Реакции","Редактировать","Переслать","Удалить у всех"}:new String[]{"Ответить","Реакции","Переслать"};new AlertDialog.Builder(this,android.R.style.Theme_Material_NoActionBar).setTitle(m.preview).setItems(items,(d,which)->{String it=items[which];if(it.equals("Ответить"))setReply(m);else if(it.equals("Реакции"))reactionPanel(m);else if(it.equals("Редактировать"))editMsg(m);else if(it.equals("Переслать"))forward(m);else if(it.equals("Удалить у всех"))Rt.deleteForAll(chat,m.id,new Rt.Done(){public void ok(){}public void fail(String e){Tui.toast(ChatActivity.this,e);}});}).show();}
    private void reactionPanel(Msg m){String[] e={"heart","fire","smile","cry"};String[] show={"❤️","🔥","😂","😢"};new AlertDialog.Builder(this).setTitle("Реакция").setItems(show,(d,w)->Rt.react(chat,m.id,e[w],true)).show();}
    private void editMsg(Msg m){EditText e=Tui.input(this,"Новый текст");e.setText(m.text);new AlertDialog.Builder(this).setTitle("Редактировать").setView(e).setPositiveButton("Сохранить",(d,w)->Rt.edit(chat,m.id,peer,e.getText().toString(),m.payload,new Rt.Done(){public void ok(){}public void fail(String er){Tui.toast(ChatActivity.this,er);}})).setNegativeButton("Отмена",null).show();}
    private void forward(Msg m){EditText e=Tui.input(this,"Кому @username");new AlertDialog.Builder(this).setTitle("Переслать").setView(e).setPositiveButton("Отправить",(d,w)->{String u=Rt.cleanUser(e.getText().toString());Rt.db().child("usernames").child(u).get().addOnSuccessListener(s->{String id=s.getValue(String.class);if(id==null)Tui.toast(this,"@ не найден");else Rt.send(id,m.payload,new Rt.Done(){public void ok(){Tui.toast(ChatActivity.this,"Переслано");}public void fail(String er){Tui.toast(ChatActivity.this,er);}});});}).setNegativeButton("Отмена",null).show();}
    private void chatMenu(){String[] it={"Экспорт выбранных сообщений","Сменить мой ключ","Очистить локальный кеш"};new AlertDialog.Builder(this).setTitle("Чат").setItems(it,(d,w)->{if(w==0)exportSelected();else if(w==1){TsuyuApp.app().crypto.rotate();HashMap<String,Object> m=new HashMap<>();m.put("publicKey",TsuyuApp.app().crypto.publicKey());m.put("keyId",TsuyuApp.app().crypto.keyId());m.put("keyRing",TsuyuApp.app().crypto.publicRing().toString());Rt.updateProfile(m,new Rt.Done(){public void ok(){Tui.toast(ChatActivity.this,"Ключ обновлён");}public void fail(String e){Tui.toast(ChatActivity.this,e);}});}else{TsuyuApp.app().index.close();Tui.toast(this,"Кеш будет обновлён заново");}}).show();}
    private void exportSelected(){if(msgs.isEmpty()){Tui.toast(this,"Нет сообщений");return;}String[] labels=new String[msgs.size()];boolean[] checked=new boolean[msgs.size()];for(int i=0;i<msgs.size();i++){labels[i]=Tui.time(msgs.get(i).ts)+" · "+msgs.get(i).preview;checked[i]=true;}new AlertDialog.Builder(this).setTitle("Что экспортировать").setMultiChoiceItems(labels,checked,(d,w,on)->checked[w]=on).setPositiveButton("Экспорт",(d,w)->writeExport(checked)).setNegativeButton("Отмена",null).show();}
    private void writeExport(boolean[] checked){try{JSONArray arr=new JSONArray();for(int i=0;i<msgs.size();i++)if(checked[i]){Msg m=msgs.get(i);arr.put(new JSONObject().put("id",m.id).put("from",m.sender).put("time",m.ts).put("text",m.text).put("type",m.type).put("payload",m.payload));}JSONObject out=new JSONObject().put("app","Tsuyu").put("chatId",chat).put("peer",peerName).put("exportedAt",System.currentTimeMillis()).put("messages",arr);File dir=new File(getExternalFilesDir(null),"exports");dir.mkdirs();File f=new File(dir,"Tsuyu-chat-"+System.currentTimeMillis()+".json");try(FileOutputStream os=new FileOutputStream(f)){os.write(out.toString(2).getBytes("UTF-8"));}Uri outUri=FileProvider.getUriForFile(this,"app.tsuyu.mobile.fileprovider",f);Intent share=new Intent(Intent.ACTION_SEND).setType("application/json").putExtra(Intent.EXTRA_STREAM,outUri).addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);startActivity(Intent.createChooser(share,"Экспорт Tsuyu"));}catch(Exception e){Tui.toast(this,e.getMessage());}}
    private void detach(){if(msgListener!=null)Rt.db().child("chats").child(chat).child("messages").removeEventListener(msgListener);if(presListener!=null)Rt.db().child("presence").child(peer).removeEventListener(presListener);if(typingListener!=null)Rt.db().child("typing").child(chat).child(peer).removeEventListener(typingListener);} 
    private String status(String key,String def){return getSharedPreferences("ui",0).getString("label_"+key,def);}private long lv(DataSnapshot s,long d){Object v=s.getValue();if(v instanceof Number)return ((Number)v).longValue();try{return Long.parseLong(String.valueOf(v));}catch(Exception e){return d;}}private int dp(int v){return (int)(v*getResources().getDisplayMetrics().density+.5f);} 
    static class Msg{String id,sender,receiver,type,text,reply,preview="";boolean mine,edited;long ts,reactions;JSONObject payload;JSONArray media;}
    class MsgAdapter extends RecyclerView.Adapter<MsgAdapter.H>{class H extends RecyclerView.ViewHolder{LinearLayout wrap,bub;H(View v){super(v);wrap=(LinearLayout)v;bub=(LinearLayout)wrap.getChildAt(0);}}@Override public H onCreateViewHolder(android.view.ViewGroup p,int vt){LinearLayout w=new LinearLayout(ChatActivity.this);w.setOrientation(LinearLayout.VERTICAL);w.setPadding(dp(8),dp(4),dp(8),dp(4));LinearLayout b=new LinearLayout(ChatActivity.this);b.setOrientation(LinearLayout.VERTICAL);b.setPadding(dp(12),dp(8),dp(12),dp(8));w.addView(b,new LinearLayout.LayoutParams(-2,-2));return new H(w);}@Override public void onBindViewHolder(H h,int pos){Msg m=msgs.get(pos);h.bub.removeAllViews();h.wrap.setGravity(m.mine?Gravity.RIGHT:Gravity.LEFT);h.bub.setBackground(Tui.round(m.mine?0xff1f3b34:0xff1c1c20,18));if(!m.reply.isEmpty())h.bub.addView(Tui.text(ChatActivity.this,"↪ ответ",12,false));if(m.media!=null)for(int i=0;i<m.media.length();i++){MediaTools.Pack p=MediaTools.fromJson(m.media.optJSONObject(i));h.bub.addView(mediaView(p));}if(!m.text.isEmpty()){TextView t=Tui.text(ChatActivity.this,m.text,textSize,false);t.setTextColor(Tui.FG);h.bub.addView(t);}TextView meta=Tui.text(ChatActivity.this,Tui.time(m.ts)+(m.edited?" · изм":"")+(m.reactions>0?" · ❤ "+m.reactions:""),11,false);h.bub.addView(meta);h.bub.setOnLongClickListener(v->{messageMenu(m);return true;});h.bub.setOnClickListener(new View.OnClickListener(){long last;public void onClick(View v){long now=System.currentTimeMillis();if(now-last<290){Rt.heart(chat,m.id,true);Tui.bounce(v);}last=now;}});Tui.press(h.bub);}@Override public int getItemCount(){return msgs.size();}}
    private View mediaView(MediaTools.Pack p){LinearLayout box=new LinearLayout(this);box.setOrientation(LinearLayout.VERTICAL);box.setPadding(0,0,0,dp(6));if(p.kind.equals("voice")){WaveView w=new WaveView(this,p.bytes);box.addView(w,new LinearLayout.LayoutParams(dp(220),dp(46)));box.addView(Tui.text(this,"Голосовое · "+p.duration+" c",12,false));return box;}if(p.kind.equals("audio")){ProgressBar pr=new ProgressBar(this,null,android.R.attr.progressBarStyleHorizontal);pr.setProgress(38);box.addView(pr,new LinearLayout.LayoutParams(dp(220),dp(8)));box.addView(Tui.text(this,p.name.isEmpty()?"Аудио":p.name,12,false));box.setOnClickListener(v->openPack(p));return box;}if(p.kind.equals("photo")||p.kind.equals("video")||p.kind.equals("circle")){ImageView iv=new ImageView(this);String img=p.thumb==null||p.thumb.isEmpty()?p.base64:p.thumb;Bitmap bm=Tui.bitmap(img);if(bm!=null)iv.setImageBitmap(bm);iv.setScaleType(ImageView.ScaleType.CENTER_CROP);int size=p.kind.equals("circle")?dp(190):dp(230);box.addView(iv,new LinearLayout.LayoutParams(size,p.kind.equals("circle")?size:dp(160)));box.addView(Tui.text(this,p.kind.equals("photo")?"Фото":"▶ "+(p.kind.equals("circle")?"Кружочек":"Видео"),12,false));box.setOnClickListener(v->openPack(p));return box;}box.addView(Tui.text(this,MediaTools.preview(p.kind,null),12,false));return box;}
    private void openPack(MediaTools.Pack p){String id=MediaVault.put(p);startActivity(new Intent(this,MediaViewerActivity.class).putExtra("mediaId",id));}
    public static class WaveView extends View{Paint p=new Paint(1);int seed;public WaveView(Context c,int s){super(c);seed=s;p.setColor(Tui.ACCENT);}protected void onDraw(Canvas c){super.onDraw(c);int w=getWidth(),h=getHeight(),n=34;Random r=new Random(seed);for(int i=0;i<n;i++){float x=i*w/(float)n;float bh=(.25f+r.nextFloat()*.75f)*h;c.drawRoundRect(x,h/2-bh/2,x+w/(float)n*.55f,h/2+bh/2,6,6,p);}}}
}
